const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json.user_input || '';
  let sanitized = raw;
  let redactions = 0;

  const maskCard = () => { redactions++; return '[CARD-REDACTED]'; };

  // Visa: 13-16 digits starting with 4, optional spaces or hyphens between groups
  sanitized = sanitized.replace(/\b4[0-9]{3}(?:[\s\-]?[0-9]{4}){2}[\s\-]?[0-9]{1,4}\b/g, maskCard);

  // Mastercard: 16 digits, 51-55 series and 2221-2720 (2-series) simplified to 22-27
  sanitized = sanitized.replace(/\b(?:5[1-5]|2[2-7])[0-9]{2}(?:[\s\-]?[0-9]{4}){3}\b/g, maskCard);

  // Amex: 15 digits starting with 34 or 37, formatted 4-6-5
  sanitized = sanitized.replace(/\b3[47][0-9]{2}[\s\-]?[0-9]{6}[\s\-]?[0-9]{5}\b/g, maskCard);

  // Discover: 16 digits starting with 6011 or 65xx
  sanitized = sanitized.replace(/\b6(?:011|5[0-9]{2})[\s\-]?(?:[0-9]{4}[\s\-]?){3}\b/g, maskCard);

  // CVV/CVC/CID: 3-4 digit security codes following a keyword
  sanitized = sanitized.replace(/\b(?:cvv2?|cvc2?|cid|security\s+code)[:\s]+([0-9]{3,4})\b/gi, (m, digits) => {
    redactions++;
    return m.slice(0, m.length - digits.length) + '[CVV-REDACTED]';
  });

  // Card expiry dates: MM/YY or MM/YYYY
  sanitized = sanitized.replace(/\b(0[1-9]|1[0-2])\/([0-9]{2}|[0-9]{4})\b/g, () => { redactions++; return '[EXPIRY-REDACTED]'; });

  results.push({
    json: {
      ...item.json,
      sanitized_input: sanitized,
      pci_scan: {
        had_pci_data: redactions > 0,
        redaction_count: redactions,
        scan_status: redactions > 0 ? 'masked' : 'clean'
      }
    }
  });
}

return results;
